{
  "id": 13,
  "knowledge": "Environmental Instability Event",
  "description": "Identifies periods when showcase environmental conditions fluctuate beyond acceptable parameters.",
  "definition": "Occurs when the 24-hour temperature variation exceeds 1\u00b0C OR the 24-hour humidity variation exceeds 3% within a 24-hour period."
}

{
  "id": 27,
  "knowledge": "Temperature Reading Implications",
  "description": "Illustrates temperature readings and their conservation implications.",
  "definition": "Ideal for most collections is 18-22\u00b0C. Fluctuations greater than 2\u00b0C within 24 hours can stress materials. Values outside 10-30\u00b0C may indicate control failure."
}

{
  "id": 2,
  "knowledge": "Environmental Risk Factor (ERF)",
  "description": "Quantifies the overall environmental risk to an artifact based on its sensitivities.",
  "definition": "Calculated as the average of an artifact's various environmental sensitivity scores. These scores are derived by converting qualitative ratings (e.g., 'Low', 'High') to numbers using 'Sensitivity Weight Values'."
}

{
  "id": 31,
  "knowledge": "Total Environmental Threat Level (TETL)",
  "description": "Comprehensive measurement of all environmental threats to an artifact based on multiple risk factors.",
  "definition": "Calculated as: 'Environmental Risk Factor (ERF)' + 'Light Exposure Risk (LER)' + ('Material Deterioration Rate (MDR)' * 2)."
}

{
  "id": 39,
  "knowledge": "Environmental Compliance Index (ECI)",
  "description": "Measures how well current environmental conditions meet the requirements for an artifact.",
  "definition": "Calculated as: 10 - (absolute difference in temperature from ideal + absolute difference in humidity from ideal / 5 + 'Environmental Risk Factor' / 2). Higher values are better."
}

{
  "id": 24,
  "knowledge": "Humidity Sensitivity Levels",
  "description": "Illustrates humidity sensitivity classifications and their implications.",
  "definition": "Values include 'Low' (can tolerate a wide range of humidity), 'Medium' (requires a controlled humidity range), and 'High' (requires a very stable and narrow humidity range)."
}

{
  "id": 57,
  "knowledge": "Humidity Exposure Thresholds",
  "description": "Defines maximum safe humidity exposure levels for artifacts based on material sensitivity.",
  "definition": "High sensitivity artifacts must not exceed 55% RH; Medium sensitivity artifacts must not exceed 60% RH."
}

{
  "id": 54,
  "knowledge": "Conservation Environment Chronology (CEC)",
  "description": "A methodological approach to segment environmental monitoring data into chronological intervals.",
  "definition": "Involves grouping environmental readings by fixed time intervals (such as by year) to discern patterns and inform conservation strategies."
}

args.sql:
SELECT COUNT(*) FROM (
    SELECT e."readTS", e."tempVar24", e."RHvar"
    FROM "EnvironmentalReadingsCore" e
    WHERE e."tempVar24" > 1 OR e."RHvar" > 3
) sub;

SELECT COUNT(*) FROM "SurfaceAndPhysicalReadings" s
JOIN "EnvironmentalReadingsCore" e ON s."env_link" = e."monitor_code"
WHERE date_part('year', e."readTS")::int >= 2023;
